using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Security.Cryptography;
using System.Text;
using System.Web.Script.Serialization;
namespace ClearSpace {
public static class RulePackBatchTests {
 public static void Verify(string root,Action<bool,string> check){
  Func<Action,bool> rejects=action=>{try{action();return false;}catch{return true;}};var json=new JavaScriptSerializer();string inputs=Path.Combine(root,"batch-inputs");Directory.CreateDirectory(inputs);var store=new RulePackCatalog(Path.Combine(root,"batch-store"));
  Func<string,string,string> file=(name,raw)=>{string path=Path.Combine(inputs,name);File.WriteAllText(path,raw);return path;};var legacy=json.Deserialize<ApplicationRulePack>(RulePackTests.Raw());legacy.Schema=1;legacy.PackId=null;legacy.Name=null;legacy.Rules[0].Conditions=null;string rawLegacy=json.Serialize(legacy);
  string a=file("alpha.json",RulePackTests.Raw("batch-alpha")),b=file("legacy.json",rawLegacy),bad=file("bad.json","{not-json");var plan=RulePackBatch.Prepare(store,new[]{a,b,bad});check(plan.Items.Count(i=>i.Ready)==2&&plan.Items.Count(i=>i.Error!=null)==1&&!Directory.Exists(store.DirectoryPath),"Batch preparation validates each file without importing any definitions");var result=plan.Apply(store);check(result.Added==2&&result.Failed==1&&store.List().Count==2,"Mixed batch imports valid files and reports a malformed file separately");check(store.List().All(p=>!p.Enabled)&&store.List().Select(p=>p.FileName).OrderBy(n=>n).SequenceEqual(new[]{"alpha.json","legacy.json"}),"Each new JSON file retains its filename and starts disabled");var old=store.List().Single(p=>p.FileName=="legacy.json");check(old.Loaded.Pack.Schema==1&&old.Loaded.Raw==rawLegacy,"Legacy JSON is stored unchanged instead of rewriting its payload");
  store.SetEnabled(old.Id,true);legacy.Version="1.1.0";file("legacy.json",json.Serialize(legacy));result=RulePackBatch.Prepare(store,new[]{b}).Apply(store);check(result.Updated==1&&store.List().Single(p=>p.Id==old.Id).Enabled,"A higher legacy file version upgrades in place and preserves enablement");var restored=store.Rollback(old.Id);check(restored.Loaded.Raw==rawLegacy&&restored.FileName=="legacy.json","Rollback restores the previous legacy payload and file identity");
  result=RulePackBatch.Prepare(store,new[]{a}).Apply(store);check(result.Skipped==1&&result.Added==0&&result.Updated==0,"Reimporting an identical file skips it without making a new pack");string sameVersion=file("edited.json",RulePackTests.Raw("batch-alpha").Replace("Example cache rules","Edited rules"));plan=RulePackBatch.Prepare(store,new[]{sameVersion});check(plan.Items.Single().Error!=null&&plan.Apply(store).Failed==1,"Edited definitions cannot overwrite an existing pack at the same version");
  string duplicate=file("duplicate.json",RulePackTests.Raw("batch-alpha","2.0.0"));plan=RulePackBatch.Prepare(store,new[]{a,duplicate});check(plan.Items.All(i=>i.Error!=null)&&!plan.Items.Any(i=>i.Ready),"Conflicting pack IDs in one selection are rejected without depending on file order");
  string renamed=file("renamed.json",RulePackTests.Raw("batch-alpha","2.0.0"));store.SetEnabled("batch-alpha",true);result=RulePackBatch.Prepare(store,new[]{renamed}).Apply(store);check(result.Updated==1&&store.List().Single(p=>p.Id=="batch-alpha").FileName=="renamed.json","Schema 2 IDs preserve pack identity when an upgrade file is renamed");check(store.Rollback("batch-alpha").FileName=="alpha.json","Rollback also restores the previous displayed filename");
  var second=store.Import(rawLegacy,"another-legacy.json");check(second.Id!=old.Id&&second.Loaded.Pack.Rules[0].Id==old.Loaded.Pack.Rules[0].Id,"Different legacy filenames remain independent even when rule IDs are equal");
  string c=file("cancel.json",RulePackTests.Raw("cancel-pack"));check(rejects(()=>RulePackBatch.Prepare(store,new[]{c},new CancellationToken(true))),"Cancelled batch preparation stops before loading the selected files");result=RulePackBatch.Prepare(store,new[]{c}).Apply(store,new CancellationToken(true));check(result.Cancelled&&result.Skipped==1&&!store.List().Any(p=>p.Id=="cancel-pack"),"Cancelled batch application leaves pending files unimported");check(rejects(()=>RulePackBatch.Prepare(store,Enumerable.Repeat(a,21))),"Batch selection is capped before reading more than twenty files");
  using(var rsa=new RSACryptoServiceProvider(2048,new CspParameters{ProviderType=24,Flags=CspProviderFlags.CreateEphemeralKey})){rsa.PersistKeyInCsp=false;byte[] payload=Encoding.UTF8.GetBytes(rawLegacy);string signed=json.Serialize(new SignedRuleEnvelope{Payload=Convert.ToBase64String(payload),Signature=Convert.ToBase64String(rsa.SignData(payload,CryptoConfig.MapNameToOID("SHA256")))});var signedStore=new RulePackCatalog(Path.Combine(root,"signed-legacy"),rsa.ToXmlString(false));var signedEntry=signedStore.Import(signed,"signed.json");check(signedEntry.Loaded.Trust=="发布者签名已验证"&&signedEntry.Loaded.Raw==signed,"Legacy multi-file import preserves and verifies the original signed envelope");check(signedStore.List().Single().Loaded.Raw==signed,"Reloading a signed legacy import retains its exact signed payload");}
  string locked=file("locked.json",RulePackTests.Raw("locked-pack"));using(var held=new FileStream(locked,FileMode.Open,FileAccess.Write,FileShare.None)){check(RulePackBatch.Prepare(store,new[]{locked}).Items.Single().Error!=null,"An import cannot read rules while another writer holds the file");}
  var preferences=new CleanerSettings{UseWinapp2=false,AutomaticUpdates=true,UpdateUrl="not-a-url"};RuleSourcePreferences.SaveWinapp2(preferences,true,false,()=>{});check(preferences.Winapp2Enabled&&preferences.JsonEnabled&&preferences.AutoJson&&preferences.UpdateUrl=="not-a-url","Winapp2 preferences do not validate or mutate an unrelated JSON endpoint");check(rejects(()=>RuleSourcePreferences.SaveJson(preferences,false,false,"https://example.test/rules.json",()=>{throw new IOException("fixture");}))&&preferences.JsonEnabled&&preferences.AutoJson&&preferences.UpdateUrl=="not-a-url","A failed JSON preference save restores only its own fields");
  string temp=Path.Combine(Path.GetTempPath(),"ClarityJsonBatch-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(temp,"Cache"));try{legacy.Rules[0].Paths=new[]{"%TEMP%\\"+Path.GetFileName(temp)+"\\Cache"};var loaded=new RuleStore().Read(json.Serialize(legacy),true);var discovery=new DiscoveryResult{Applications=new List<ApplicationIdentity>{new ApplicationIdentity{Name="Fixture App",Executable=Path.Combine(temp,"fixture.exe"),InstallDirectory=temp}}};var first=new InstalledRulePack{Id="legacy-one",Loaded=loaded};var other=new InstalledRulePack{Id="legacy-two",Loaded=loaded};var rules=RulePackCatalog.Compile(first,discovery,CancellationToken.None).Concat(RulePackCatalog.Compile(other,discovery,CancellationToken.None)).ToList();check(rules.Count==2&&rules.Select(r=>r.Id).Distinct().Count()==2&&rules.All(r=>r.Id.StartsWith("library-pack-")),"Legacy files compile into separate rule namespaces with mandatory external-rule protection");}finally{if(Path.GetFullPath(temp).StartsWith(Path.GetFullPath(Path.GetTempPath()).TrimEnd('\\')+"\\ClarityJsonBatch-",StringComparison.OrdinalIgnoreCase)&&Engine.SafeAncestors(Path.Combine(temp,"probe")))Directory.Delete(temp,true);}
 }
}
}
